/**
 * 🟢 ✨ Gajjala entry marks on the REAL board (2026-11-12, spec §3.5 / §4 WP-FE). Ajay 2026-11-12 ~15:22 ET: "Can you show me
 * green on these tabs some indicators to show be which ones have best potential entries right now I am clicking through
 * each one and figuring out... an Indicator or new tickers with in last 30 mins like blinkers or something would be nice".
 *
 * HAND payloads only: the 2026-10-13 hand fixture deep-cloned, `entry_marks` / `new_mark` injected here (the goldens under
 * __fixtures__ are regenerated by the backend recipe, never edited by this file). Pins: the chip badge + blinker draw the
 * served block for their own sub key; the chip's textContent is byte-identical with and without marks (the
 * GajjalaBoard.test.tsx:77 shape); the card mark sits LAST in the card's chip row with the served text; an older API / an
 * invalid or expired block draws nothing; the same marks on the 1-minute and 🧪 Audited pages.
 */
import { cleanup, render, screen, waitFor, within } from '@testing-library/react';
import { MemoryRouter } from 'react-router-dom';
import { afterEach, describe, expect, it, vi } from 'vitest';
import hand from './__fixtures__/gajjala_board_2026_10_13.json';

vi.mock('../hooks/useUser', () => ({ useCurrentUser: () => ({ user: null, loading: false }) }));
vi.mock('../lib/usageTracker', () => ({ trackFeature: () => undefined }));
vi.mock('./PatternChart', () => ({ PatternChart: (props: any) => <div data-testid={`chart-${props.tile.symbol}`} /> }));
vi.mock('./GrowthChip', () => ({ GrowthChip: ({ symbol }: any) => <span data-testid={`growth-${symbol}`} /> }));
vi.mock('./ShortInterestChip', () => ({ ShortInterestChip: ({ symbol }: any) => <span data-testid={`short-${symbol}`} /> }));
vi.mock('./ExplosiveChip', () => ({ ExplosiveChip: () => <span data-testid="explosive" /> }));
vi.mock('./EnterableChip', () => ({ EnterableChip: () => <span data-testid="enterable" /> }));
vi.mock('./RulesInfo', () => ({ RulesInfo: ({ section }: any) => <span data-testid="rules-info">{section}</span> }));
vi.mock('../hooks/useBounceRoom', () => ({
  useBounceRoom: () => ({ map: new Map(), payload: null, loading: false, error: null, pending: 0 }),
}));

import GajjalaBoard from './GajjalaBoard';

const clone = (x: any) => JSON.parse(JSON.stringify(x));
const HAND: Record<string, any> = (hand as any).boards;
const iso = (ms: number) => new Date(ms).toISOString();
const AHEAD = () => iso(Date.now() + 20 * 60_000);
const BEHIND = () => iso(Date.now() - 60_000);

const GREEN_TITLE = '🟢 2 close to an entry — served title · UNMEASURED';
const NEW_TITLE = '✨ served chip blinker title';
const MARK = (until: string) => ({ kind: 'listed', at_et: '15:01', until, text: 'new 15:01 ET',
                                   title: 'served card blinker title · display only' });

/** The bull_flag hand board, timers off, with the given `entry_marks` and per-symbol `new_mark` injected. */
function board(opts: { marks?: any; tileMarks?: Record<string, any>; tab?: string; tf?: string } = {}): any {
  const b = clone(HAND.bull_flag);
  b.session = { ...b.session, refresh_sec: 0 };
  if (opts.tab) b.tab = opts.tab;
  if (opts.tf) { b.tf = opts.tf; b.tiles = b.tiles.map((t: any) => ({ ...t, tf: opts.tf })); }
  if (opts.marks !== undefined) b.entry_marks = opts.marks;
  if (opts.tileMarks) b.tiles = b.tiles.map((t: any) => (t.symbol in opts.tileMarks! ? { ...t, new_mark: opts.tileMarks![t.symbol] } : t));
  return b;
}
const RULES = { sections: { gajjala: { title: 'R', emoji: '\u{1F6A9}', picks: [], stops: [], alerts: [], note: 'N' } } };
function stub(make: () => any) {
  const spy = vi.fn(async (url: string) => {
    const u = new URL(String(url), 'http://x');
    const ok = (body: any) => ({ ok: true, status: 200, json: async () => clone(body) });
    if (u.pathname.endsWith('/scan')) return ok({ state: 'closed', latest_at: null, text: 'served closed line' });
    if (u.pathname.endsWith('/entry-tape')) return ok({ id: 'x', bars: [], rules: [], lite: true });
    if (u.pathname.includes('/chart-maps/gajjala')) return ok(make());
    if (u.pathname.endsWith('/supply-demand/rules')) return ok(RULES);
    return ok({});
  });
  vi.stubGlobal('fetch', spy);
  return spy;
}
const mount = (variant?: 'gajjala_1m' | 'gajjala_audited') => render(
  <MemoryRouter initialEntries={['/chart-maps?tab=gajjala&sub=bull_flag']}>
    {variant ? <GajjalaBoard variant={variant} /> : <GajjalaBoard />}
  </MemoryRouter>);
const subButtons = () => screen.getAllByRole('tab').filter((b) => b.getAttribute('data-testid')?.startsWith('gg-sub-'));
const pinned = () => HAND.bull_flag.subs.map((s: any) => `${s.emoji} ${s.label} · ${s.count}`);

const FULL = () => ({ subs: {
  bull_flag: { green: { n: 2, label: '2', title: GREEN_TITLE }, new: { n: 1, until: AHEAD(), title: NEW_TITLE } },
  intraday_vcp: { green: { n: 12, label: '12', title: 'served vcp title' } },
  kiss_fly: { new: { n: 1, until: AHEAD(), title: 'served kiss blinker' } },
} });

afterEach(() => { cleanup(); vi.unstubAllGlobals(); vi.restoreAllMocks(); });

describe('GajjalaBoard — 🟢 sub chip marks', () => {
  it('served green → the badge on ITS chip with the served label + title; blinker only where served', async () => {
    stub(() => board({ marks: FULL() }));
    mount();
    await screen.findByTestId('gg-tile-PFAI');
    const bf = screen.getByTestId('gg-sub-bull_flag');
    const g = within(bf).getByTestId('gg-sub-green-bull_flag');
    expect(g).toHaveAttribute('data-label', '2');
    expect(g).toHaveAttribute('title', GREEN_TITLE);
    expect(g).toHaveClass('gg-sub-green');
    expect(within(bf).getByTestId('gg-sub-new-bull_flag')).toHaveAttribute('title', NEW_TITLE);
    expect(within(screen.getByTestId('gg-sub-intraday_vcp')).getByTestId('gg-sub-green-intraday_vcp')).toHaveAttribute('data-label', '12');
    expect(within(screen.getByTestId('gg-sub-kiss_fly')).getByTestId('gg-sub-new-kiss_fly')).toBeTruthy();
    expect(within(screen.getByTestId('gg-sub-kiss_fly')).queryByTestId('gg-sub-green-kiss_fly')).toBeNull();
    for (const k of ['horizontal_fade', 'reversal_squeeze', 'premarket', 'postmarket', 'playbook']) {
      const btn = screen.getByTestId(`gg-sub-${k}`);
      expect(btn.querySelector('.gg-sub-green, .gg-sub-new')).toBeNull();
    }
  });

  it('the chip textContent is byte-identical with and without marks (the :77 pin shape)', async () => {
    stub(() => board({ marks: FULL() }));
    mount();
    await screen.findByTestId('gg-tile-PFAI');
    const withMarks = subButtons().map((b) => b.textContent);
    expect(withMarks).toEqual(pinned());
    cleanup();
    stub(() => board());
    mount();
    await screen.findByTestId('gg-tile-PFAI');
    expect(subButtons().map((b) => b.textContent)).toEqual(withMarks);
  });

  it('NEGATIVE: no entry_marks (older API) → no mark element anywhere', async () => {
    stub(() => board());
    const { container } = mount();
    await screen.findByTestId('gg-tile-PFAI');
    expect(container.querySelector('.gg-sub-green, .gg-sub-new, .gg-new-mark, .gg-new-dot')).toBeNull();
  });

  it('NEGATIVE: null / empty subs / n 0 / missing label / non-string title → nothing', async () => {
    for (const marks of [null, {}, { subs: null }, { subs: {} },
                         { subs: { bull_flag: { green: { n: 0, label: '0', title: 't' } } } },
                         { subs: { bull_flag: { green: { n: 2, title: 't' } } } },
                         { subs: { bull_flag: { green: { n: 2, label: '2', title: 5 } } } },
                         { subs: { bull_flag: { new: { n: 1, until: 'not a time', title: 't' } } } }]) {
      stub(() => board({ marks }));
      const { container } = mount();
      await screen.findByTestId('gg-tile-PFAI');
      expect(container.querySelector('.gg-sub-green, .gg-sub-new')).toBeNull();
      expect(subButtons().map((b) => b.textContent)).toEqual(pinned());
      cleanup();
    }
  });

  it('new: an until in the past → no blinker (the green stays)', async () => {
    stub(() => board({ marks: { subs: { bull_flag: { green: { n: 1, label: '1', title: 't' },
                                                    new: { n: 1, until: BEHIND(), title: NEW_TITLE } } } } }));
    mount();
    await screen.findByTestId('gg-tile-PFAI');
    expect(screen.queryByTestId('gg-sub-new-bull_flag')).toBeNull();
    expect(screen.getByTestId('gg-sub-green-bull_flag')).toHaveAttribute('data-label', '1');
  });

  it('NEGATIVE: a block under an unknown sub key draws on no chip', async () => {
    stub(() => board({ marks: { subs: { not_a_sub: { green: { n: 3, label: '3', title: 't' } } } } }));
    const { container } = mount();
    await screen.findByTestId('gg-tile-PFAI');
    expect(container.querySelector('.gg-sub-green')).toBeNull();
  });
});

describe('GajjalaBoard — ✨ card mark', () => {
  it('new_mark → gg-new-<SYM> LAST in gg-chips-<SYM>, served text + title; the other chips unchanged', async () => {
    stub(() => board());
    mount();
    await screen.findByTestId('gg-tile-PFAI');
    const before = Array.from(screen.getByTestId('gg-chips-PFAI').children).map((c) => c.getAttribute('data-testid'));
    cleanup();
    stub(() => board({ tileMarks: { PFAI: MARK(AHEAD()) } }));
    mount();
    await screen.findByTestId('gg-tile-PFAI');
    const row = screen.getByTestId('gg-chips-PFAI');
    const m = within(row).getByTestId('gg-new-PFAI');
    expect(m.textContent).toBe('new 15:01 ET');
    expect(m).toHaveAttribute('title', 'served card blinker title · display only');
    expect(row.lastElementChild).toBe(m);
    expect(Array.from(row.children).slice(0, -1).map((c) => c.getAttribute('data-testid'))).toEqual(before);
    expect(screen.queryByTestId('gg-new-BKYI')).toBeNull();
  });

  it('NEGATIVE: expired / absent / invalid new_mark → no card mark', async () => {
    stub(() => board({ tileMarks: { PFAI: MARK(BEHIND()), BKYI: null, TCRT: { ...MARK(AHEAD()), text: '' } } }));
    const { container } = mount();
    await screen.findByTestId('gg-tile-PFAI');
    expect(container.querySelector('.gg-new-mark')).toBeNull();
  });
});

describe('GajjalaBoard — the same marks on the 1-minute and 🧪 Audited pages', () => {
  for (const [variant, tab, tf] of [['gajjala_1m', 'gajjala_1m', '1m'], ['gajjala_audited', 'gajjala_audited', undefined]] as const) {
    it(`${variant}: chip green + blinker + card mark render from the served block`, async () => {
      const spy = stub(() => board({ marks: FULL(), tileMarks: { BKYI: MARK(AHEAD()) }, tab, tf }));
      mount(variant);
      await screen.findByTestId('gg-tile-BKYI');
      await waitFor(() => expect(spy.mock.calls.some((c: any[]) => String(c[0]).includes(variant === 'gajjala_1m' ? 'gajjala-1m' : 'gajjala-audited'))).toBe(true));
      expect(screen.getByTestId('gg-sub-green-bull_flag')).toHaveAttribute('data-label', '2');
      expect(screen.getByTestId('gg-sub-new-kiss_fly')).toBeTruthy();
      expect(within(screen.getByTestId('gg-chips-BKYI')).getByTestId('gg-new-BKYI').textContent).toBe('new 15:01 ET');
      expect(subButtons().map((b) => b.textContent)).toEqual(pinned());
    });
  }
});
